CREATE VIEW "public"."meal_rag_data" AS
 SELECT m.id,
    m.name,
    m.description,
    m.meal_type,
    m.cooking_time,
    m.calories,
    m.protein,
    m.fat,
    m.carbs,
    m.diet_type,
    m.allergens,
    m.tags,
    string_agg((((p.name::text || ' '::text) || mp.quantity) || ' '::text) || p.unit::text, ', '::text ORDER BY p.name) AS ingredients,
    (((((((((((((((((((((((((m.name::text || '. '::text) || m.description) || '. '::text) || 'Тип: '::text) || m.meal_type::text) || '. '::text) || 'Калории: '::text) || m.calories) || '. '::text) || 'Белки: '::text) || m.protein) || ' г. '::text) || 'Жиры: '::text) || m.fat) || ' г. '::text) || 'Углеводы: '::text) || m.carbs) || ' г. '::text) || 'Тип питания: '::text) || m.diet_type::text) || '. '::text) || 'Теги: '::text) || array_to_string(m.tags, ', '::text)) || '. '::text) || 'Ингредиенты: '::text) || string_agg((((p.name::text || ' '::text) || mp.quantity) || ' '::text) || p.unit::text, ', '::text ORDER BY p.name) AS rag_text
   FROM meals m
     LEFT JOIN meal_products mp ON mp.meal_id = m.id
     LEFT JOIN products p ON p.id = mp.product_id
  WHERE m.status::text = 'published'::text
  GROUP BY m.id, m.name, m.description, m.meal_type, m.cooking_time, m.calories, m.protein, m.fat, m.carbs, m.diet_type, m.allergens, m.tags;;

CREATE VIEW "public"."meals_with_products" AS
 SELECT m.id,
    m.name,
    m.description,
    m.meal_type,
    m.cooking_time,
    m.calories,
    m.protein,
    m.fat,
    m.carbs,
    m.diet_type,
    m.allergens,
    m.tags,
    json_agg(json_build_object('product_id', p.id, 'name', p.name, 'quantity', mp.quantity, 'unit', p.unit) ORDER BY p.name) AS products
   FROM meals m
     LEFT JOIN meal_products mp ON mp.meal_id = m.id
     LEFT JOIN products p ON p.id = mp.product_id
  WHERE m.status::text = 'published'::text
  GROUP BY m.id, m.name, m.description, m.meal_type, m.cooking_time, m.calories, m.protein, m.fat, m.carbs, m.diet_type, m.allergens, m.tags;;
